// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a block timestamp to influence the pseudorandom result
    function testFuzz_property(address caller, uint256 warpTimestamp) public {
        // admissible caller must be non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // keep timestamp in a wide but reasonable range
        warpTimestamp = bound(warpTimestamp, 1, type(uint64).max);

        // ensure the caller has funds to pay the ticket
        uint256 ticket = 10; // must match contract constant TICKET_AMOUNT
        vm.deal(caller, ticket);

        // set block timestamp to influence random in contract
        vm.warp(warpTimestamp);

        // perform the call as the fuzzed caller
        vm.prank(caller);
        c.play{value: ticket}();

        // The universal property to assert: if the contract's internal random resulted
        // in taking the winner branch (in reference when random==0), the reference
        // guarantees pot is reset to 0 after the call. We cannot read random directly,
        // but we can assert the conservative rule that pot is either 0 or equals the
        // ticket just contributed when the branch did not fire; importantly the
        // reference always sets pot to 0 in the branch for some randomness values.
        // We assert that pot is either 0 or equal to the ticket (i.e., no other value)
        // which holds for the reference for every single play call, but the mutant
        // will produce a different pot value for some inputs.

        // Read pot via public getter and assert the general invariant
        uint256 pot = c.pot();

        // The reference C: after a single play call starting from pot==0,
        // pot can only be 0 (if winner branch fired) or ticket (if branch did not fire).
        // This is the single assertion the reference satisfies for all inputs, and the
        // mutant (which flips the branch condition) can leave pot with a different
        // accumulated value for the same inputs in some cases, causing this assertion
        // to fail on the mutant for some fuzzed inputs.
        assertTrue(pot == 0 || pot == ticket);
    }
}

