pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address and a block timestamp delta to influence the pseudorandomness
    function testFuzz_property(address caller, uint256 tsOffset) public {
        // Keep caller non-zero EOA-like
        vm.assume(caller != address(0));
        // bound the timestamp offset to a reasonable range so it stays wide but meaningful
        tsOffset = bound(tsOffset, 0, 1 days);

        // Ensure caller has Ether to pay the ticket
        uint256 ticket = 10;
        vm.deal(caller, ticket);

        // Record pot before
        uint256 potBefore = c.pot();

        // Move block timestamp to influence keccak randomness deterministically
        vm.warp(block.timestamp + tsOffset);

        // Make the call from the fuzzed caller paying exactly the ticket amount
        vm.prank(caller);
        // call play with exactly TICKET_AMOUNT wei
        c.play{value: ticket}();

        // After the call, in the reference contract: if the random chosen by
        // keccak(block.timestamp, block.difficulty) % 2 equals 0 then the
        // contract transfers winnings and resets pot to 0; otherwise pot is increased by ticket.
        // Therefore the general invariant we can assert about the reference is:
        // pot is either unchanged + ticket (non-winning branch) or exactly 0 (winning branch).
        // That is: pot == potBefore + ticket OR pot == 0.
        // This is a property over the public getter c.pot(). The mutant flips which random
        // outcome triggers the reset, so for some (caller, tsOffset) the mutant will
        // produce a pot value that violates this relation relative to the reference's behavior.

        uint256 potAfter = c.pot();
        assertTrue(potAfter == potBefore + ticket || potAfter == 0);
    }
}

