pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address as the caller and a uint256 to control block.timestamp
    function testFuzz_property(address caller, uint256 ts) public {
        // Keep caller as a non-zero address
        vm.assume(caller != address(0));
        // ticket amount is 10 in the contract; we must send exactly that
        uint256 ticket = 10;

        // bound timestamp to a reasonable range to avoid extreme warp issues
        ts = bound(ts, 1, type(uint64).max);
        vm.warp(ts);

        // fund the caller so they can send the ticket
        vm.deal(caller, ticket);

        // make the call as the fuzzed caller sending exactly the ticket
        vm.prank(caller);
        c.play{value: ticket}();

        // The reference contract resets pot to 0 whenever
        // random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0.
        // We compute that same random here (using the same on-chain sources available to the contract)
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // Assert: if random == 0 then pot must be 0. This is true for the reference for all inputs,
        // and the mutant (which triggers the win when random == 1) will leave pot nonzero for some inputs
        // where random == 0, causing this assertion to fail there.
        if (random == 0) {
            assertTrue(c.pot() == 0);
        } else {
            // when random != 0 we cannot assert anything universal about pot, so assert true to keep a single assert form
            assertTrue(true);
        }
    }
}

