pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address actor and a uint256 ts to influence the derived randomness
    function testFuzz_property(address actor, uint256 ts) public {
        // admissible domain: actor must be non-zero EOA-like and we constrain ts to a practical range
        vm.assume(actor != address(0));
        // ticket amount is 10 in the contract; ensure actor has enough balance
        uint256 ticket = 10;
        vm.deal(actor, 1 ether);

        // set block.timestamp to the fuzzed ts so the contract's randomness can take either value
        // keep ts within a wide, realistic range
        uint256 boundedTs = bound(ts, 1, type(uint32).max);
        vm.warp(boundedTs);

        // make an initial play to populate pot (so a winning payout will reset it to 0)
        vm.prank(actor);
        c.play{value: ticket}();

        // After the play, compute the derived randomness our property targets.
        // We replicate the contract's randomness formula to decide the admissible branch condition.
        uint256 random = uint256(keccak256(abi.encodePacked(boundedTs, block.difficulty))) % 2;

        // The universal property we assert: whenever this derived random == 0, the reference contract
        // (proper behavior) will have pot == 0 after the call (it paid out and reset pot).
        // This should hold for ALL admissible inputs on the reference, but the mutant that flips
        // the condition to random==1 will fail for some inputs (those with random==0).
        if (random == 0) {
            assertTrue(c.pot() == 0);
        } else {
            // If random != 0 we cannot assert about pot (could be 0 or >0), so assert true trivially
            assertTrue(true);
        }
    }
}

