pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We will fuzz the timestamp so we can force the derived random to be 0.
    // The property: when random==0 (i.e. keccak256(ts, diff) % 2 == 0), reference resets pot to 0 after play.
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 fuzzTimestamp) public {
        // Keep the timestamp in a reasonable EVM range
        vm.assume(fuzzTimestamp > 0 && fuzzTimestamp < type(uint32).max);

        // Ensure block.difficulty is some deterministic value we control so the fuzzer can hit random==0
        uint256 difficulty = 0xABCDEF; // constant difficulty

        // We need the derived random to be 0. Compute it off-chain and assume that the fuzzTimestamp we got satisfies it.
        bytes32 h = keccak256(abi.encodePacked(uint256(fuzzTimestamp), difficulty));
        vm.assume(uint256(h) % 2 == 0);

        // Give an external caller some ETH and make the call paying exactly TICKET_AMOUNT
        address player = address(0xBEEF);
        vm.deal(player, 100 ether);

        // Set block.timestamp and block.difficulty to our chosen values
        vm.warp(fuzzTimestamp);
        vm.roll(1);
        // Note: Foundry does not provide vm.setblockdifficulty; instead we rely on using the same difficulty in hash above
        // but we can set block.difficulty via vm.store is disallowed. However the contract's randomness uses block.difficulty
        // To keep the admissible domain matching the reference, we will set block.timestamp so that with the current
        // block.difficulty the computed hash parity is even. To be conservative, we also assume that the live block.difficulty
        // parity combined with fuzzTimestamp yields even. Recompute using current block.difficulty.

        // Recompute and assume using actual block.difficulty to ensure the property holds in the environment
        bytes32 h2 = keccak256(abi.encodePacked(uint256(fuzzTimestamp), block.difficulty));
        vm.assume(uint256(h2) % 2 == 0);

        // Call play paying exactly 10 wei (TICKET_AMOUNT)
        uint256 ticket = 10;
        vm.prank(player);
        c.play{value: ticket}();

        // After the call, the reference C should have pot == 0 because random==0 triggers payout+reset
        // The mutant that flips the condition will (for this same chosen timestamp/difficulty) leave pot != 0.
        assertTrue(c.pot() == 0);
    }
}

