pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: a caller address that the fuzzer will vary (must be non-zero)
    function testFuzz_property(address caller) public {
        // keep caller admissible
        vm.assume(caller != address(0));

        // fund the caller so they can pay the ticket
        uint256 ticket = 10; // matches C.TICKET_AMOUNT
        vm.deal(caller, ticket);

        // We need to drive c.play() into the winning branch (random == 0).
        // The reference uses keccak(block.timestamp, block.difficulty) % 2 for randomness.
        // We can try repeatedly calling play until we observe a run that ends with pot == 0.
        // The invariant we assert is: after any single call to play that pays exactly the ticket and completes,
        // if the contract executed the winning branch then pot() must be 0. We will fuzz caller and rely on
        // repeated attempts within the single test invocation to encounter a winning outcome.

        // Attempt multiple times (still a single fuzzed invocation) to reach the winning branch.
        // If the reference is correct, when a winning branch occurs pot is 0 afterwards. The mutant may leave pot > 0.

        bool sawWinningAndPotZero = false;

        // Try up to 16 times to hit the winning branch (probability 1/2 each try); keeps domain wide
        for (uint i = 0; i < 16; i++) {
            // ensure fresh caller balance for the call
            vm.deal(caller, ticket);
            vm.prank(caller);
            // call play with exact ticket amount
            try c.play{value: ticket}() {
                // call completed; check pot value via public getter
                uint256 potAfter = c.pot();
                // If winning branch executed in reference, potAfter must be 0.
                // We cannot directly detect whether the branch executed except via pot value.
                // If potAfter == 0 then we observed a winning outcome and the reference invariant holds for this run.
                if (potAfter == 0) {
                    sawWinningAndPotZero = true;
                    break;
                }
                // else either losing branch (pot increased) or mutant left pot non-zero after payout
            } catch {
                // should not revert; ignore and continue
            }
        }

        // The single assert: for the correct contract, if any play invocation results in the winning branch,
        // then pot() after that call equals 0. We assert that we observed such a winning outcome with pot == 0.
        // This holds for the reference for all inputs; the mutant (which omits pot reset) will allow a winning
        // outcome where pot != 0, so the fuzzer can find a caller that produces such a run and make this assertion fail.
        assertTrue(sawWinningAndPotZero);
    }
}

