pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor address; the fuzzer will supply different addresses to act as callers
    function testFuzz_property(address actor) public {
        // admissible domain: actor must be non-zero and not the contract or bank
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // ensure actor has enough ETH to pay the ticket
        uint256 ticket = 10;
        vm.deal(actor, ticket);

        // actor calls play paying exactly the ticket amount
        vm.prank(actor);
        c.play{value: ticket}();

        // Read the public pot and contract balance
        uint256 potAfter = c.pot();
        uint256 balAfter = address(c).balance;

        // GENERAL RULE (single assertion): If pot is zero after play, contract balance must also be zero.
        // The reference implementation always forwards the fee when paying out, ensuring no leftover balance when pot==0.
        assertTrue(!(potAfter == 0) || (balAfter == 0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address: the fuzzer will supply various addresses (EOAs).
    // We keep the domain wide but avoid the zero address as a trivial unusable actor.
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Ensure caller has enough ETH to send the ticket
        uint256 ticket = 10;
        vm.deal(caller, ticket);

        // Caller calls play() paying exactly TICKET_AMOUNT
        vm.prank(caller);
        c.play{value: ticket}();

        // The general invariant (observed via public surface): if pot() == 0 then address(c).balance == 0
        // This holds for the reference contract for all admissible inputs but the mutant (which omits paying the fee out)
        // can leave contract balance > 0 while pot == 0 for some caller addresses; the fuzzer should find one.
        assertTrue(!(c.pot() == 0) || address(c).balance == 0);
    }
}
